1	package world
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"strings"
11	)
12	
13	// RecordInfo 描述一次保存产生的记录的元信息。
14	type RecordInfo struct {
15		// ID 是记录在存档目录内的唯一标识。
16		ID RecordID
17		// Parent 是父记录标识。只有直接建立的槽首条记录没有父记录（为空）；
18		// 分支槽首条记录以来源槽记录为父，故槽首记录的 Parent 不一定为空。
19		Parent RecordID
20		// SlotFirst 表示这是所在槽的首条记录（直接建立的根记录，或从其他
21		// 槽分出的分支首记录）；它不等价于 Parent 为空。
22		SlotFirst bool
23		// Version 是记录中世界规则的版本；History 列出它不代表该版本已被
24		// 调用方接受，用 Record 读取时仍需显式给出可接受版本集合。
25		Version string
26	}
27	
28	// slotPointer 是槽指针文件的磁盘内容，指向该槽当前最新记录。
29	//
30	// History 按该槽“保存生效的次序”记录全部属于本槽的记录标识，最新在前，
31	// 末尾是槽首条记录（直接建立的根记录或分支首记录）。它只在对应记录文件
32	// 已完整落盘后才随指针原子更新，因此绝不会包含写了一半的残留文件、写完
33	// 但尚未完成保存的孤儿记录，或 CAS 竞争失败的写入。恢复读取据此遍历，
34	// 不依赖文件修改时间，也不信任受损记录文件里读出的父标识或槽首标记。
35	//
36	// 旧版本写出的指针没有 History 字段；读取时会在内存中按校验通过的父链
37	// 回退重建，不要求用户转换数据。
38	//
39	// 顶层对象内 latest、history 各自只允许出现一次：完全同名、只改大小写或
40	// Unicode 转义还原后对应同一字段的两个名称都算重复（encoding/json 本会
41	// 静默采用后一个值），出现歧义时整份指针按损坏拒绝，而不是选一个值继续。
42	// 缺少 History 不违反这条规则；History 数组内部的重复标识是另一回事，由
43	// 读取侧按首次出现次序去重。
44	type slotPointer struct {
45		Latest  RecordID   `json:"latest"`
46		History []RecordID `json:"history,omitempty"`
47	}
48	
49	// archiveMarker 是存档目录的标记文件。
50	type archiveMarker struct {
51		Format int `json:"format"`
52	}
53	
54	// Archive 是一个本地存档目录句柄。多个进程或多个实例可以同时打开
55	// 同一目录；所有写入通过目录内的 flock 串行化。
56	type Archive struct {
57		dir string
58	}
59	
60	const (
61		markerName  = "archive.json"
62		recordsName = "records"
63		slotsName   = "slots"
64	)
65	
66	// Create 在指定目录建立新的存档。目录会被创建；若该目录已经是一个
67	// 存档则返回错误，以免覆盖已有数据。
68	//
69	// 创建有明确的结果：要么完整成功并返回可立即使用的句柄，要么返回
70	// 错误且不返回句柄。准备必要目录、写入存档标记或建立锁文件时出错，
71	// 都会把指明失败操作与位置的错误交给调用方，并撤回本次创建已产生的
72	// 标记、锁文件与子目录——回退只限本次新增的内容：目录里原有的文件与
73	// 子目录（包括原本就存在、可直接使用的空 records/slots 子目录）以及
74	// 调用前已存在的目标目录本身都保持原样。因此失败后排除障碍即可用
75	// 同一路径重新创建，不会被上一次失败留下的标记拒绝。
76	func Create(dir string) (_ *Archive, err error) {
77		// 本次调用新产生的内容，失败时按相反顺序撤回；调用前已存在的
78		// 任何内容都不在撤回范围内。
79		var created []string
80		defer func() {
81			if err != nil {
82				for i := len(created) - 1; i >= 0; i-- {
83					os.Remove(created[i])
84				}
85			}
86		}()
87	
88		// 目标目录在调用前已存在时保留它（包括失败回退时）；不存在才
89		// 由本次创建建立，并纳入回退范围。
90		if _, statErr := os.Stat(dir); statErr != nil {
91			if !errors.Is(statErr, os.ErrNotExist) {
92				return nil, fmt.Errorf("检查存档目录 %s: %w", dir, statErr)
93			}
94			if err := os.MkdirAll(dir, 0o755); err != nil {
95				return nil, fmt.Errorf("建立存档目录 %s: %w", dir, err)
96			}
97			created = append(created, dir)
98		}
99	
100		markerPath := filepath.Join(dir, markerName)
101		f, err := os.OpenFile(markerPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
102		if err != nil {
103			if errors.Is(err, os.ErrExist) {
104				// 已有存档：原样保留既有标记（即使它无法解析），不覆盖，
105				// 也不借回退删除；此时本次尚未产生任何新内容。
106				return nil, &ConflictError{Reason: "目录已是一个存档: " + dir}
107			}
108			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
109		}
110		created = append(created, markerPath)
111		markerData, _ := json.Marshal(archiveMarker{Format: archiveFormatVersion})
112		if _, err := f.Write(markerData); err != nil {
113			f.Close()
114			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
115		}
116		if err := f.Close(); err != nil {
117			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
118		}
119	
120		for _, sub := range []string{recordsName, slotsName} {
121			subPath := filepath.Join(dir, sub)
122			if fi, statErr := os.Stat(subPath); statErr == nil {
123				if !fi.IsDir() {
124					return nil, fmt.Errorf("建立存档子目录 %s: 位置已被同名文件占用", subPath)
125				}
126				// 原本就存在的子目录直接沿用，回退时保留。
127				continue
128			} else if !errors.Is(statErr, os.ErrNotExist) {
129				return nil, fmt.Errorf("检查存档子目录 %s: %w", subPath, statErr)
130			}
131			if err := os.Mkdir(subPath, 0o755); err != nil {
132				return nil, fmt.Errorf("建立存档子目录 %s: %w", subPath, err)
133			}
134			created = append(created, subPath)
135		}
136	
137		// 预先建立锁文件并同步目录，使之后的打开更稳妥。锁位置已被占用
138		// （例如已是一个目录）时明确报错，而不是留到首次保存才失败。
139		lockPath := filepath.Join(dir, "lock")
140		_, lockStatErr := os.Stat(lockPath)
141		lockExisted := lockStatErr == nil
142		if lockStatErr != nil && !errors.Is(lockStatErr, os.ErrNotExist) {
143			return nil, fmt.Errorf("检查存档锁文件 %s: %w", lockPath, lockStatErr)
144		}
145		lf, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o600)
146		if err != nil {
147			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
148		}
149		if err := lf.Close(); err != nil {
150			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
151		}
152		if !lockExisted {
153			created = append(created, lockPath)
154		}
155	
156		if err := syncDir(dir); err != nil {
157			return nil, fmt.Errorf("同步存档目录 %s: %w", dir, err)
158		}
159		return &Archive{dir: dir}, nil
160	}
161	
162	// Open 打开一个此前由 Create 建立的存档目录。
163	func Open(dir string) (*Archive, error) {
164		path := filepath.Join(dir, markerName)
165		f, err := os.Open(path)
166		if err != nil {
167			if errors.Is(err, os.ErrNotExist) {
168				return nil, &NotFoundError{}
169			}
170			return nil, err
171		}
172		defer f.Close()
173		var m archiveMarker
174		if err := json.NewDecoder(f).Decode(&m); err != nil {
175			return nil, &CorruptError{Reason: "存档标记无法解析"}
176		}
177		if m.Format != archiveFormatVersion {
178			return nil, &CorruptError{Reason: "不支持的存档格式版本"}
179		}
180		for _, sub := range []string{recordsName, slotsName} {
181			if fi, err := os.Stat(filepath.Join(dir, sub)); err != nil || !fi.IsDir() {
182				return nil, &CorruptError{Reason: "存档目录结构不完整: 缺少 " + sub}
183			}
184		}
185		return &Archive{dir: dir}, nil
186	}
187	
188	// Dir 返回存档目录路径。
189	func (a *Archive) Dir() string { return a.dir }
190	
191	func (a *Archive) slotPath(slot string) string {
192		return filepath.Join(a.dir, slotsName, slot+".json")
193	}
194	
195	// validSlotName 拒绝空名以及可能逃逸 slots 目录的名字。
196	func validSlotName(slot string) bool {
197		if slot == "" || slot == "." || slot == ".." {
198			return false
199		}
200		if filepath.IsAbs(slot) {
201			return false
202		}
203		for _, r := range slot {
204			if r == '/' || r == '\\' || r == 0 {
205				return false
206			}
207		}
208		return filepath.Clean(slot) == slot
209	}
210	
211	// readSlotPointerLocked 在调用方已持锁的前提下读取并解析槽指针文件。
212	//
213	// 除 JSON 语法外，还要检查顶层对象内 latest 与 history 两个字段是否各自
214	// 重复出现：encoding/json 对同一字段静默采用后一个值（history 甚至整体
215	// 替换前一份），于是读到的当前世界或可浏览的历史会随字段书写次序变化。
216	// 出现这种歧义时整个指针按损坏拒绝，绝不选其中一个值继续；判定方式与
217	// encoding/json 选择字段一致——完全同名、只改大小写的写法，以及 Unicode
218	// 转义还原后对应同一字段的写法都算同一字段重复，两个值相同、其中一个为
219	// 空、后一份历史更完整或所指记录校验通过都不豁免，交换先后次序同样损坏。
220	// 名称只出现一次时，本就可接受的大小写与转义写法照常读取；缺少 history
221	// 是旧版本合法指针，不算重复。history 数组内部同一记录标识重复出现属于
222	// 另一回事，沿用既有的去重与次序规则。
223	func (a *Archive) readSlotPointerLocked(slot string) (slotPointer, error) {
224		data, err := os.ReadFile(a.slotPath(slot))
225		if err != nil {
226			if errors.Is(err, os.ErrNotExist) {
227				return slotPointer{}, &NotFoundError{Slot: slot}
228			}
229			return slotPointer{}, err
230		}
231		// 重复字段检查只依赖 JSON 语法结构（键与容器边界），不依赖值类型，因此
232		// 先于 Unmarshal 的类型错误：即使重复字段的某个值类型不对、解码失败，
233		// 也要明确报字段重复，而不是笼统的无法解析。
234		if dup, ok := duplicatePointerField(data); ok {
235			return slotPointer{}, &CorruptError{
236				Slot:   slot,
237				Reason: fmt.Sprintf("槽指针字段 %q 重复出现：同一对象内有两个名称会被读取为该字段，槽指针含义有歧义", dup),
238			}
239		}
240		var p slotPointer
241		if err := json.Unmarshal(data, &p); err != nil {
242			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
243		}
244		if p.Latest == "" {
245			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针为空"}
246		}
247		return p, nil
248	}
249	
250	// duplicatePointerField 检查槽指针 JSON 顶层对象内 latest、history 两个
251	// 固定字段是否各自重复出现。槽指针是只有这两个字段的扁平对象，检查只需
252	// 遍历顶层键、不进入任何值容器；history 数组元素是值而非字段名，数组内
253	// 同一记录标识重复出现不在此判定。
254	//
255	// 键按 JSON 转义还原后的字符串与字段标签做大小写不敏感匹配，与
256	// encoding/json 对结构体字段的选择一致：因此 "latest" 与 "Latest"、
257	// "history" 与写作 Unicode 转义形式的同一名称（如 "latest"）都会
258	// 归并到同一字段，任一字段第二次出现即返回该字段标签。文本已通过
259	// json.Unmarshal，这里不会再遇到语法问题。
260	func duplicatePointerField(data []byte) (string, bool) {
261		dec := json.NewDecoder(bytes.NewReader(data))
262		dec.UseNumber()
263		tok, err := dec.Token()
264		if err != nil {
265			return "", false
266		}
267		d, ok := tok.(json.Delim)
268		if !ok || d != '{' {
269			return "", false
270		}
271		seen := map[string]bool{}
272		for {
273			tok, err := dec.Token()
274			if err != nil {
275				return "", false
276			}
277			if d, ok := tok.(json.Delim); ok && d == '}' {
278				return "", false
279			}
280			key, ok := tok.(string)
281			if !ok {
282				return "", false
283			}
284			field := ""
285			switch {
286			case strings.EqualFold(key, "latest"):
287				field = "latest"
288			case strings.EqualFold(key, "history"):
289				field = "history"
290			}
291			if field != "" {
292				if seen[field] {
293					return field, true
294				}
295				seen[field] = true
296			}
297			// 跳过该键对应的值（标量直接取下一个 token；数组或对象整体跳过），
298			// 使下一轮仍停留在顶层键或右花括号上。
299			if err := skipJSONValue(dec); err != nil {
300				return "", false
301			}
302		}
303	}
304	
305	// skipJSONValue 消费刚读入键之后的那一个 JSON 值：标量只需再读一个 token，
306	// 数组或对象按配对的分隔符整体跳过，不把其中内容当作顶层字段。
307	func skipJSONValue(dec *json.Decoder) error {
308		tok, err := dec.Token()
309		if err != nil {
310			return err
311		}
312		d, ok := tok.(json.Delim)
313		if !ok {
314			return nil
315		}
316		var open, close byte
317		switch d {
318		case '{':
319			open, close = '{', '}'
320		case '[':
321			open, close = '[', ']'
322		default:
323			return nil
324		}
325		depth := 1
326		for depth > 0 {
327			t, err := dec.Token()
328			if err != nil {
329				return err
330			}
331			if td, ok := t.(json.Delim); ok {
332				switch byte(td) {
333				case open:
334					depth++
335				case close:
336					depth--
337				}
338			}
339		}
340		return nil
341	}
342	
343	// readLatestLocked 在调用方已持锁的前提下读取槽当前最新记录标识。
344	func (a *Archive) readLatestLocked(slot string) (RecordID, error) {
345		p, err := a.readSlotPointerLocked(slot)
346		if err != nil {
347			return "", err
348		}
349		return p.Latest, nil
350	}
351	
352	// Save 在存档中保存一个世界。
353	//
354	// 首次保存会创建同名存档槽；槽名已存在时返回 *ConflictError。
355	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。槽位上已
356	// 有指针但无法解析或顶层字段重复（含义有歧义）时返回 *CorruptError，不把
357	// 该槽当作可写入的新槽或旧槽处理，也不创建任何记录。
358	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
359		if !validSlotName(slot) {
360			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
361		}
362		st := w.Snapshot()
363	
364		lock, err := acquireLock(a.dir)
365		if err != nil {
366			return RecordInfo{}, err
367		}
368		defer lock.release()
369	
370		// 持锁后再次确认槽不存在。
371		if _, err := a.readLatestLocked(slot); err == nil {
372			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
373		} else if !errors.As(err, new(*NotFoundError)) {
374			return RecordInfo{}, err
375		}
376	
377		id, err := newRecordID()
378		if err != nil {
379			return RecordInfo{}, err
380		}
381		env := &envelope{
382			Format:    recordFormatVersion,
383			ID:        id,
384			SlotFirst: true,
385			State:     st,
386		}
387		env.Checksum = computeChecksum(env)
388		if err := writeRecord(a.dir, env); err != nil {
389			return RecordInfo{}, err
390		}
391		if err := a.createSlotPointer(slot, id); err != nil {
392			return RecordInfo{}, err
393		}
394		return RecordInfo{ID: id, SlotFirst: true, Version: st.Rules.Version}, nil
395	}
396	
397	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
398	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
399	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。新槽的
400	// 历史索引只含其首条记录本身——分支槽不会把来源槽的记录计入候选。
401	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
402		slotsDir := filepath.Join(a.dir, slotsName)
403		final := a.slotPath(slot)
404		data, _ := json.MarshalIndent(slotPointer{
405			Latest:  id,
406			History: []RecordID{id},
407		}, "", "  ")
408	
409		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
410		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
411		if err != nil {
412			return err
413		}
414		if _, err := f.Write(data); err != nil {
415			f.Close()
416			os.Remove(tmp)
417			return err
418		}
419		if err := f.Sync(); err != nil {
420			f.Close()
421			os.Remove(tmp)
422			return err
423		}
424		if err := f.Close(); err != nil {
425			os.Remove(tmp)
426			return err
427		}
428		if err := os.Link(tmp, final); err != nil {
429			os.Remove(tmp)
430			if errors.Is(err, os.ErrExist) {
431				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
432			}
433			return err
434		}
435		os.Remove(tmp)
436		return syncDir(slotsDir)
437	}
438	
439	// Replace 用世界当前状态覆盖槽的最新记录。
440	//
441	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
442	// 写入才会发生；否则返回 *ConflictError——即使该标识对应的旧文件恰好
443	// 已损坏或被删除，过期请求也只报冲突，不改报文件错误。标识匹配时还要
444	// 确认这条当前记录本身可正常读取：文件缺失返回 *NotFoundError；格式版本
445	// 不受支持、截断、校验和不匹配、世界状态不合法或父记录缺失返回
446	// *CorruptError。绝不用
447	// 调用方传入的完整世界掩盖当前记录的问题，也不自动改选较老记录为父。
448	// 新记录的父记录就是被覆盖的那次记录。同一目录下并发覆盖同一父记录时
449	// 只有一个成功。被拒绝的覆盖不改变槽指向、历史与任何已有记录。槽指针
450	// 无法解析，或顶层 latest/history 字段重复（含义有歧义）时按 *CorruptError
451	// 拒绝：无法确定当前记录与待承接的历史，不保存新记录，也不自动修补指针。
452	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
453		if !validSlotName(slot) {
454			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
455		}
456		if expected == "" {
457			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
458		}
459		st := w.Snapshot()
460	
461		lock, err := acquireLock(a.dir)
462		if err != nil {
463			return RecordInfo{}, err
464		}
465		defer lock.release()
466	
467		pointer, err := a.readSlotPointerLocked(slot)
468		if err != nil {
469			return RecordInfo{}, err
470		}
471		if pointer.Latest != expected {
472			return RecordInfo{}, &ConflictError{
473				Slot:   slot,
474				Reason: "所依据的记录已不是该槽最新记录",
475			}
476		}
477	
478		// 标识匹配后，当前记录本身必须可正常读取：格式受支持、完整、内容
479		// 校验通过、世界状态合法且父记录关系成立。否则以它为父保存的新记录随后也
480		// 无法读取，等于用调用方传入的完整世界掩盖了当前记录的问题；
481		// 这里沿用与读取路径一致的校验，损坏或缺失时拒绝覆盖，槽指向、
482		// 历史与已有记录保持原样，调用方可改走恢复预览与确认恢复。
483		if _, err := a.loadAndVerifyLocked(expected); err != nil {
484			if ce, ok := err.(*CorruptError); ok {
485				ce.Slot = slot
486			}
487			return RecordInfo{}, err
488		}
489	
490		// 覆盖保存传入世界的快照，以被覆盖的当前记录为父，沿用共同的
491		// 新记录组装、落盘与槽指针提交路径。
492		return a.appendSlotRecordLocked(slotSave{
493			slot:          slot,
494			oldPointer:    pointer,
495			parent:        expected,
496			historyAnchor: expected,
497			state:         st,
498		})
499	}
500	
501	// commitSlotPointerLocked 在记录文件已完整落盘后，原子更新槽指针：指向
502	// 新记录，并把历史索引按保存次序前置新记录。历史索引只在此刻（记录已
503	// 完整生效）才更新，因此残留临时文件与写完但未完成保存的孤儿记录绝不会
504	// 进入恢复候选。
505	func (a *Archive) commitSlotPointerLocked(slot string, oldPointer slotPointer, oldLatest, newID RecordID) error {
506		history, err := a.nextSlotHistoryLocked(oldPointer, oldLatest, newID)
507		if err != nil {
508			return err
509		}
510		return a.persistSlotPointerLocked(slot, slotPointer{Latest: newID, History: history})
511	}
512	
513	// replaceSlotPointer 直接把槽指针指向 id，不附带历史索引。它仅用于测试
514	// 中模拟旧版本或外部写入器留下的指针；生产写入路径一律走
515	// commitSlotPointerLocked 以维护历史索引。
516	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
517		return a.persistSlotPointerLocked(slot, slotPointer{Latest: id})
518	}
519	
520	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
521	//
522	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
523	// 目标槽名已存在时返回 *ConflictError；目标槽指针无法解析或顶层字段重复
524	// 时返回带目标槽名的 *CorruptError，不覆盖损坏槽也不在其中创建记录。
525	// 源记录必须校验通过，且源槽指针必须可读：无法解析或顶层字段重复时返回
526	// 带源槽名的 *CorruptError，无法确认来源属于该槽就不分出新槽。
527	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
528		if !validSlotName(srcSlot) {
529			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
530		}
531		if !validSlotName(dstSlot) {
532			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
533		}
534		if src == "" {
535			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
536		}
537	
538		lock, err := acquireLock(a.dir)
539		if err != nil {
540			return RecordInfo{}, err
541		}
542		defer lock.release()
543	
544		srcEnv, err := a.loadAndVerifyLocked(src)
545		if err != nil {
546			return RecordInfo{}, err
547		}
548		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
549		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
550			return RecordInfo{}, err
551		}
552		// 目标槽重名拒绝创建。
553		if _, err := a.readLatestLocked(dstSlot); err == nil {
554			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
555		} else if !errors.As(err, new(*NotFoundError)) {
556			return RecordInfo{}, err
557		}
558	
559		id, err := newRecordID()
560		if err != nil {
561			return RecordInfo{}, err
562		}
563		env := &envelope{
564			Format:    recordFormatVersion,
565			ID:        id,
566			Parent:    src,
567			SlotFirst: true,
568			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
569			State: cloneState(srcEnv.State),
570		}
571		env.Checksum = computeChecksum(env)
572		if err := writeRecord(a.dir, env); err != nil {
573			return RecordInfo{}, err
574		}
575		if err := a.createSlotPointer(dstSlot, id); err != nil {
576			return RecordInfo{}, err
577		}
578		return RecordInfo{
579			ID:        id,
580			Parent:    src,
581			SlotFirst: true,
582			Version:   env.State.Rules.Version,
583		}, nil
584	}
585	
586	// assertInSlotHistoryLocked 确认 id 位于 slot 自身的历史次序中（分支槽
587	// 的历史只含它自己保存成功的记录，不含来源槽记录）。
588	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
589		history, err := a.slotHistoryLocked(slot)
590		if err != nil {
591			return err
592		}
593		for _, cid := range history {
594			if cid == id {
595				return nil
596			}
597		}
598		return &NotFoundError{Slot: slot, Record: id}
599	}
600	
601	// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
602	// 槽首记录在末尾）。
603	//
604	// 优先使用指针内嵌的历史索引；旧版本指针没有该索引时，在内存中沿
605	// “校验通过”的记录父链回退重建，绝不在读取路径上改写目录。重建在缺失、
606	// 无法解析或校验不过的记录处停止——无法确认归属的更老记录不再使用。
607	// 槽首标记只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首
608	// 标记既不能把遍历引向别的槽，也不能遮住本槽更早的可用记录。
609	func (a *Archive) slotHistoryLocked(slot string) ([]RecordID, error) {
610		p, err := a.readSlotPointerLocked(slot)
611		if err != nil {
612			return nil, err
613		}
614		if len(p.History) > 0 {
615			// 以 Latest 为链头做一次去重规范化，容忍索引中的重复项。
616			return dedupeRecordIDs(append([]RecordID{p.Latest}, p.History...)), nil
617		}
618		return a.rebuildHistoryLocked(p.Latest)
619	}
620	
621	// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史，
622	// 只返回仍能确认属于本槽的记录；在缺失、无法解析或校验不过的记录处停止。
623	func (a *Archive) rebuildHistoryLocked(latest RecordID) ([]RecordID, error) {
624		var chain []RecordID
625		seen := map[RecordID]bool{}
626		cur := latest
627		for cur != "" {
628			if seen[cur] {
629				return nil, &CorruptError{Record: cur, Reason: "历史链出现环"}
630			}
631			seen[cur] = true
632			env, err := a.loadAndVerifyLocked(cur)
633			if err != nil {
634				// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
635				// 旧历史在此断裂；已确认的部分仍可使用。
636				return chain, nil
637			}
638			chain = append(chain, cur)
639			if env.SlotFirst {
640				return chain, nil
641			}
642			cur = env.Parent
643		}
644		return chain, nil
645	}
646	
647	// dedupeRecordIDs 按首次出现次序去重记录标识。
648	func dedupeRecordIDs(ids []RecordID) []RecordID {
649		seen := map[RecordID]bool{}
650		out := ids[:0]
651		for _, id := range ids {
652			if id == "" || seen[id] {
653				continue
654			}
655			seen[id] = true
656			out = append(out, id)
657		}
658		return out
659	}
660	
661	// persistSlotPointerLocked 以原子改名写出槽指针。
662	func (a *Archive) persistSlotPointerLocked(slot string, p slotPointer) error {
663		data, _ := json.MarshalIndent(p, "", "  ")
664		return writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data)
665	}
666	
667	// nextSlotHistory 在一次以 oldLatest 为被覆盖/升级记录的成功写入后，
668	// 生成新指针应持有的历史次序：新记录在最前，其余沿用此前已确认属于
669	// 本槽的记录。旧指针无索引时在内存中回退重建（不完整也照样承接），
670	// 从而让旧历史在第一次成功覆盖或升级后获得完整恢复能力。
671	func (a *Archive) nextSlotHistoryLocked(oldPointer slotPointer, oldLatest, newID RecordID) ([]RecordID, error) {
672		base := oldPointer.History
673		if len(base) == 0 {
674			rebuilt, err := a.rebuildHistoryLocked(oldLatest)
675			if err != nil {
676				return nil, err
677			}
678			base = rebuilt
679		}
680		return dedupeRecordIDs(append([]RecordID{newID}, base...)), nil
681	}
682	
683	// Slots 返回所有存档槽名。
684	func (a *Archive) Slots() ([]string, error) {
685		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
686		if err != nil {
687			return nil, err
688		}
689		var names []string
690		for _, e := range entries {
691			if e.IsDir() {
692				continue
693			}
694			name := e.Name()
695			if len(name) > 5 && name[len(name)-5:] == ".json" {
696				names = append(names, name[:len(name)-5])
697			}
698		}
699		return names, nil
700	}
701

