1	package world
2	
3	import (
4		"bytes"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io"
12		"os"
13		"path/filepath"
14		"strings"
15		"unicode/utf8"
16	)
17	
18	// RecordID 是一次成功保存产生的、在同一存档目录内唯一的记录标识。
19	type RecordID string
20	
21	// archiveFormatVersion 是存档目录布局版本，写入目录标记中。
22	const archiveFormatVersion = 1
23	
24	// recordFormatVersion 是当前唯一支持的记录格式版本。记录格式与存档目录
25	// 布局版本是两个独立的编号：目录可打开不代表其中每条记录都能被理解，
26	// 格式编号不是该值的记录（缺失、零、负值或其他正整数）一律按损坏处理，
27	// 即使其校验和匹配、世界状态合法。
28	const recordFormatVersion = 1
29	
30	// envelope 是记录文件在磁盘上的完整编码。
31	type envelope struct {
32		// Format 是记录格式版本。
33		Format int `json:"format"`
34		// ID 是本条记录的唯一标识。
35		ID RecordID `json:"id"`
36		// Parent 是父记录标识；直接建立的槽首条记录为空。
37		Parent RecordID `json:"parent,omitempty"`
38		// SlotFirst 标记本条记录是否为其所在槽的首条记录
39		// （直接建立的根记录，或从其他槽分出的分支记录）。
40		SlotFirst bool `json:"slotFirst"`
41		// Checksum 是对（格式版本、ID、父记录、首记录标记、完整世界状态）
42		// 计算出的内容校验和，因此父记录关系也被纳入校验。
43		Checksum string `json:"checksum"`
44		// State 是完整世界数据：种子、规则与全部状态。
45		State State `json:"state"`
46	}
47	
48	// checksumPayload 是参与校验和计算的规范内容。
49	type checksumPayload struct {
50		Format    int      `json:"format"`
51		ID        RecordID `json:"id"`
52		Parent    RecordID `json:"parent"`
53		SlotFirst bool     `json:"slotFirst"`
54		State     State    `json:"state"`
55	}
56	
57	func computeChecksum(e *envelope) string {
58		p := checksumPayload{
59			Format:    e.Format,
60			ID:        e.ID,
61			Parent:    e.Parent,
62			SlotFirst: e.SlotFirst,
63			State:     e.State,
64		}
65		// encoding/json 对 map 按键排序输出，同一状态总是得到相同字节。
66		b, _ := json.Marshal(p)
67		sum := sha256.Sum256(b)
68		return hex.EncodeToString(sum[:])
69	}
70	
71	// newRecordID 产生目录内唯一的记录标识。
72	func newRecordID() (RecordID, error) {
73		var b [16]byte
74		if _, err := rand.Read(b[:]); err != nil {
75			return "", err
76		}
77		return RecordID("r" + hex.EncodeToString(b[:])), nil
78	}
79	
80	func recordPath(dir string, id RecordID) string {
81		return filepath.Join(dir, "records", string(id)+".json")
82	}
83	
84	// writeRecord 将一条记录以“先临时文件后原子改名”的方式落盘，
85	// 并校验目标文件名此前不存在，保证记录标识不会复用或混写。
86	func writeRecord(slotDir string, e *envelope) error {
87		final := recordPath(slotDir, e.ID)
88		data, err := json.MarshalIndent(e, "", "  ")
89		if err != nil {
90			return err
91		}
92	
93		// O_EXCL：即便极小概率撞到重复 ID，也绝不会覆盖别的记录。
94		f, err := os.OpenFile(final+".tmp",
95			os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
96		if err != nil {
97			return err
98		}
99		tmpName := f.Name()
100		clean := true
101		defer func() {
102			if clean {
103				os.Remove(tmpName)
104			}
105		}()
106	
107		if _, err := f.Write(data); err != nil {
108			f.Close()
109			return err
110		}
111		if err := f.Sync(); err != nil {
112			f.Close()
113			return err
114		}
115		if err := f.Close(); err != nil {
116			return err
117		}
118		if err := os.Rename(tmpName, final); err != nil {
119			return err
120		}
121		clean = false
122		if err := syncDir(filepath.Dir(final)); err != nil {
123			return err
124		}
125		return nil
126	}
127	
128	// loadRecord 读取并解析一条记录文件，但不做校验。
129	//
130	// 解析前先做文本编码检查：encoding/json 会把记录中的无效 UTF-8 字节和
131	// 字符串值、对象键里不成对的 Unicode 代理项转义悄悄改写成替换字符“�”，
132	// 随后才做内容校验——若原记录本就含有合法的“�”，改写后的文本甚至可能
133	// 仍通过校验和检查，文件损坏便被掩盖。因此无效字节与不成对的代理项转义
134	// 必须在解析前按原始字节拒绝，整条记录视为损坏，绝不用替换字符补齐后
135	// 继续交付。
136	//
137	// 解析后还要检查同一对象内的名称是否重复出现：encoding/json 对同名字段
138	// 静默采用后一个值，只要解码后的内容与校验和匹配，一份内部自相矛盾的
139	// 记录（例如先写一个负的时间片、再用同名字段写回合法值）就会被当作完好
140	// 记录交付。因此同一对象内任何名称出现第二次，无论两个值是否相同、采用
141	// 后一个值后的世界是否合法、校验和是否匹配，整条记录都视为损坏。
142	//
143	// 对会解码到结构体固定字段的对象，判定与 encoding/json 的字段选择一致：
144	// 它对结构体字段名做大小写不敏感匹配，所以 "Time" 与 "time"、"ID" 与
145	// "id" 读写的是同一个固定字段，只换大小写就算重复，不能让后一个值遮住
146	// 前一个值。名称到数值的携带上限是 map：其键是实际角色标识而非固定字段，
147	// "hero" 与 "HERO" 是两个角色，仍按还原后的精确名称区分。
148	func loadRecord(path string) (*envelope, error) {
149		f, err := os.Open(path)
150		if err != nil {
151			return nil, err
152		}
153		defer f.Close()
154		data, err := io.ReadAll(f)
155		if err != nil {
156			return nil, err
157		}
158		if err := checkRecordText(data); err != nil {
159			return nil, err
160		}
161		var e envelope
162		if err := json.Unmarshal(data, &e); err != nil {
163			return nil, fmt.Errorf("记录无法解析: %w", err)
164		}
165		if err := checkDuplicateNames(data); err != nil {
166			return nil, err
167		}
168		return &e, nil
169	}
170	
171	// recordObjectKind 标记记录中一类 JSON 对象按何种方式判定名称重复。
172	type recordObjectKind int
173	
174	const (
175		// 以下对象解码到结构体：键是结构体的固定字段名，与 encoding/json 的
176		// 字段选择相同，按大小写不敏感方式判定是否落到同一字段。
177		objEnvelope recordObjectKind = iota
178		objState
179		objRules
180		objEdge
181		objCharacter
182		objCharacterItem
183		// objMap 解码到 map（携带上限）：键是实际角色标识而非固定字段，必须
184		// 按还原后的精确名称区分，hero 与 HERO 是两个角色。
185		objMap
186		// objUnknown 是不属于记录结构的多余对象（如被忽略的未知字段值），
187		// 其中没有登记的固定字段，键按还原后的精确名称判定。
188		objUnknown
189	)
190	
191	// recordFieldNames 列出每类结构体对象登记的固定字段名（Go 字段名），用于
192	// 把 JSON 键按 encoding/json 的大小写不敏感规则归并到它会读取的字段上。
193	var recordFieldNames = func() map[recordObjectKind][]string {
194		m := make(map[recordObjectKind][]string, len(recordSchema))
195		for kind, fields := range recordSchema {
196			names := make([]string, 0, len(fields))
197			for name := range fields {
198				names = append(names, name)
199			}
200			m[kind] = names
201		}
202		return m
203	}()
204	
205	// fieldIdentity 返回一个结构体对象内 JSON 键 key 的重复判定身份：若它会被
206	// encoding/json 读取为某个固定字段（大小写不敏感，含 Unicode 转义还原后
207	// 的写法），身份就是该字段名；否则 key 不对应任何固定字段，身份用还原后
208	// 的精确名称，沿用“同一对象内同名出现第二次即损坏”的原有判定。
209	func fieldIdentity(kind recordObjectKind, key string) string {
210		if kind != objMap {
211			for _, name := range recordFieldNames[kind] {
212				if strings.EqualFold(name, key) {
213					return name
214				}
215			}
216		}
217		return key
218	}
219	
220	// recordChildKind 描述某一结构体内某个固定字段值对应的 JSON 容器类型。
221	type recordChildKind struct {
222		ch byte // 0 表示标量；'{' 表示对象，'[' 表示数组
223		// child 为 ch=='{' 时给出值对象的类型（结构体或携带上限 map）；
224		// elem 为 ch=='[' 时给出数组元素的对象类型，数组元素是标量时为 0。
225		child recordObjectKind
226		elem  recordObjectKind
227	}
228	
229	// recordSchema 描述记录中会出现的结构体对象及其固定字段，键均为 Go 字段
230	// 名（大写）。表与 envelope 及其引用的类型一一对应；新增固定字段时必须
231	// 同步登记，否则重复检查可能漏判新字段的大小写变体。表中只登记容器类型
232	// 的字段，标量字段只需出现在字段集合里、无需描述其值。
233	var recordSchema = map[recordObjectKind]map[string]recordChildKind{
234		objEnvelope: {
235			"Format":    {},
236			"ID":        {},
237			"Parent":    {},
238			"SlotFirst": {},
239			"Checksum":  {},
240			"State":     {ch: '{', child: objState},
241		},
242		objState: {
243			"Seed":       {},
244			"Rules":      {ch: '{', child: objRules},
245			"Time":       {},
246			"Characters": {ch: '[', elem: objCharacter},
247		},
248		objRules: {
249			"Version":     {},
250			"Locations":   {},
251			"Edges":       {ch: '[', elem: objEdge},
252			"ItemKinds":   {},
253			"CarryLimits": {ch: '{', child: objMap}, // 解码到 map[string]int
254		},
255		objEdge: {
256			"From": {},
257			"To":   {},
258		},
259		objCharacter: {
260			"ID":       {},
261			"Location": {},
262			"Items":    {ch: '[', elem: objCharacterItem},
263		},
264		objCharacterItem: {
265			"Item":  {},
266			"Count": {},
267		},
268		// objMap 没有固定字段；其中的键是角色标识，不登记字段名。
269		objMap: {},
270	}
271	
272	// checkDuplicateNames 检查 JSON 文本中同一对象内的名称是否重复出现。
273	//
274	// 名称按 JSON 转义还原后的字符串比较：直接写出的名称与表示同一名称的
275	// Unicode 转义（如 "ID" 与写作转义形式的同一名称）视为同一名称，不能
276	// 借此绕过限制。
277	//
278	// 对解码到结构体的对象（记录顶层、世界状态、规则、道路、角色、物品条目），
279	// 判定与 encoding/json 选择字段的方式一致：固定字段名大小写不敏感，只要
280	// 两个名称会被读取为同一个固定字段（如 "Time" 与 "time"），即使拼写大小
281	// 写不同、两个值相同或先后顺序不同，也算重复。解码到 map 的携带上限对象
282	// 不同：其中的键是实际角色标识，按还原后的精确名称比较，hero 与 HERO 是
283	// 两个角色，不能合并或误报。
284	//
285	// 判定严格按对象边界：两个不同对象各自使用相同名称是正常的（例如两个物品
286	// 条目各自有数量字段），只有同一对象内名称第二次出现才报错；字符串值中的
287	// 文字与标点不算对象名称。记录文本已经通过 json.Unmarshal 解析，这里只做
288	// 重复名称判定，语法问题不再出现。
289	func checkDuplicateNames(data []byte) error {
290		dec := json.NewDecoder(bytes.NewReader(data))
291		// UseNumber 避免数值范围差异：这里只关心对象结构与名称，不解释数值。
292		dec.UseNumber()
293		// frame 描述解析栈中的一层容器。对象记录已见过的名称身份：结构体对象
294		// 用 fieldIdentity 归并到它会读取到的固定字段名，map 与多余对象用还原
295		// 后的精确键；expectKey 跟踪下一个 token 是否为键。数组只占位并记录其
296		// 元素的对象类型，其中的字符串是值而不是名称。
297		type frame struct {
298			isObj      bool
299			kind       recordObjectKind
300			elem       recordObjectKind // 仅数组帧使用：元素是对象时的对象类型
301			elemValid  bool             // 仅数组帧使用：该数组元素是否登记为对象
302			seen       map[string]bool
303			expectKey  bool
304			pendingKey string // 刚读入、其值尚未开始的键（对象帧使用）
305		}
306		// fieldKind 返回该对象的字段 field（大小写不敏感）在其值容器为 want
307		// （'{' 或 '['）时登记的子对象类型。
308		fieldKind := func(f *frame, field string, want byte) (recordObjectKind, bool) {
309			d, ok := recordSchema[f.kind][fieldIdentity(f.kind, field)]
310			if !ok || d.ch != want {
311				return 0, false
312			}
313			if want == '{' {
314				return d.child, true
315			}
316			return d.elem, d.elem != 0
317		}
318		var stack []*frame
319		pushObject := func(kind recordObjectKind) {
320			stack = append(stack, &frame{
321				isObj:     true,
322				kind:      kind,
323				seen:      make(map[string]bool),
324				expectKey: true,
325			})
326		}
327		// 一个值（标量或容器）结束后，父对象等待下一个键。
328		markValueDone := func() {
329			if n := len(stack); n > 0 && stack[n-1].isObj {
330				stack[n-1].expectKey = true
331			}
332		}
333		for {
334			tok, err := dec.Token()
335			if err != nil {
336				// 文本已通过 json.Unmarshal，正常只会遇到 io.EOF；其余
337				// 情况不在这里报告。
338				return nil
339			}
340			if n := len(stack); n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
341				if d, ok := tok.(json.Delim); ok && d == '}' {
342					stack = stack[:n-1]
343					continue
344				}
345				key, ok := tok.(string)
346				if !ok {
347					return nil
348				}
349				parent := stack[n-1]
350				// 结构体按它会读取到的固定字段归并大小写变体；携带上限 map
351				// 与多余对象保留还原后的精确名称。
352				identity := fieldIdentity(parent.kind, key)
353				if parent.seen[identity] {
354					if parent.kind == objMap || parent.kind == objUnknown {
355						return fmt.Errorf("同一对象内名称 %q 重复出现", key)
356					}
357					return fmt.Errorf("同一对象内名称 %q 重复出现：与先前某名称会被读取为同一个固定字段", key)
358				}
359				parent.seen[identity] = true
360				parent.expectKey = false
361				parent.pendingKey = key
362				continue
363			}
364			d, isDelim := tok.(json.Delim)
365			if !isDelim {
366				markValueDone()
367				continue
368			}
369			switch d {
370			case '{':
371				kind := objUnknown
372				if n := len(stack); n > 0 {
373					parent := stack[n-1]
374					switch {
375					case parent.isObj:
376						// 父对象键对应的值对象：类型由模式表给出（如 State、
377						// Rules 是结构体，CarryLimits 是 map）。未登记的是被
378						// 结构体忽略的多余字段，按未知对象处理。
379						if k, ok := fieldKind(parent, parent.pendingKey, '{'); ok {
380							kind = k
381						}
382					case parent.elemValid:
383						// 数组中的对象元素：结构体类型由数组帧登记。
384						kind = parent.elem
385					}
386				} else {
387					// 根对象是记录信封。
388					kind = objEnvelope
389				}
390				markValueDone()
391				pushObject(kind)
392			case '[':
393				var elem recordObjectKind
394				var valid bool
395				if n := len(stack); n > 0 && stack[n-1].isObj {
396					parent := stack[n-1]
397					if d, ok := recordSchema[parent.kind][fieldIdentity(parent.kind, parent.pendingKey)]; ok && d.ch == '[' {
398						elem, valid = d.elem, d.elem != 0
399					}
400				}
401				markValueDone()
402				stack = append(stack, &frame{elem: elem, elemValid: valid})
403			case '}', ']':
404				stack = stack[:len(stack)-1]
405				markValueDone()
406			}
407		}
408	}
409	
410	// checkRecordText 校验记录文件原始字节的文本编码：JSON 文本必须是合法
411	// UTF-8；字符串值与对象键中的 \uXXXX 转义若是代理项，必须完整配对——
412	// 高位代理项（D800–DBFF）后必须紧接一个低位代理项转义（DC00–DFFF），
413	// 低位代理项不得单独出现。合法内容不受影响：真实存在的“�”、正确配对
414	// 的代理项转义与同一字符的合法转义写法都照常接受；已经转义的反斜杠
415	// （\\）其后的 uD800 只是普通文字，不是代理项转义。
416	func checkRecordText(data []byte) error {
417		if !utf8.Valid(data) {
418			return errors.New("记录包含无效 UTF-8 字节，文本编码损坏")
419		}
420		// 只需定位字符串字面量并检查其中的 \u 转义；JSON 其余部分的合法性
421		// 由 json.Unmarshal 判断。data 已是合法 UTF-8，多字节字符中不可能
422		// 出现 '"' 或 '\\' 字节。
423		i := 0
424		for i < len(data) {
425			if data[i] != '"' {
426				i++
427				continue
428			}
429			i++ // 进入字符串字面量
430			for i < len(data) {
431				c := data[i]
432				if c == '"' {
433					i++
434					break
435				}
436				if c != '\\' {
437					i++
438					continue
439				}
440				// 转义序列：\\ 是已转义的反斜杠，其后的 uD800 只是普通文字。
441				i++
442				if i >= len(data) {
443					break // 截断的转义由 json.Unmarshal 报解析错误
444				}
445				esc := data[i]
446				i++
447				if esc != 'u' {
448					continue
449				}
450				if i+4 > len(data) {
451					break // 截断的转义由 json.Unmarshal 报解析错误
452				}
453				v, ok := hex4(data[i : i+4])
454				i += 4
455				if !ok {
456					continue // 非法十六进制由 json.Unmarshal 报解析错误
457				}
458				switch {
459				case v >= 0xD800 && v <= 0xDBFF:
460					// 高位代理项必须紧接一个低位代理项转义才完整。
461					if i+6 <= len(data) && data[i] == '\\' && data[i+1] == 'u' {
462						if lo, ok := hex4(data[i+2 : i+6]); ok && lo >= 0xDC00 && lo <= 0xDFFF {
463							i += 6
464							continue
465						}
466					}
467					return fmt.Errorf("记录包含未配对的高位代理项转义 \\u%04X，Unicode 转义损坏", v)
468				case v >= 0xDC00 && v <= 0xDFFF:
469					return fmt.Errorf("记录包含单独出现的低位代理项转义 \\u%04X，Unicode 转义损坏", v)
470				}
471			}
472		}
473		return nil
474	}
475	
476	// hex4 解析 4 位十六进制数字（\uXXXX 转义的码位部分）。
477	func hex4(b []byte) (int, bool) {
478		v := 0
479		for _, c := range b {
480			v <<= 4
481			switch {
482			case c >= '0' && c <= '9':
483				v |= int(c - '0')
484			case c >= 'a' && c <= 'f':
485				v |= int(c-'a') + 10
486			case c >= 'A' && c <= 'F':
487				v |= int(c-'A') + 10
488			default:
489				return 0, false
490			}
491		}
492		return v, true
493	}
494	
495	func syncDir(dir string) error {
496		d, err := os.Open(dir)
497		if err != nil {
498			return err
499		}
500		defer d.Close()
501		return d.Sync()
502	}
503	
504	// writeAtomic 把 data 写入 dir 下的 name：同目录临时文件、fsync、
505	// 原子改名，保证崩溃后只会看到旧文件或新文件。
506	func writeAtomic(dir, name string, data []byte) error {
507		tmp := filepath.Join(dir, ".tmp-"+name+"-"+randomSuffix())
508		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
509		if err != nil {
510			return err
511		}
512		clean := true
513		defer func() {
514			if clean {
515				os.Remove(tmp)
516			}
517		}()
518		if _, err := f.Write(data); err != nil {
519			f.Close()
520			return err
521		}
522		if err := f.Sync(); err != nil {
523			f.Close()
524			return err
525		}
526		if err := f.Close(); err != nil {
527			return err
528		}
529		final := filepath.Join(dir, name)
530		if err := os.Rename(tmp, final); err != nil {
531			return err
532		}
533		clean = false
534		return syncDir(dir)
535	}
536	
537	func randomSuffix() string {
538		var b [8]byte
539		_, _ = rand.Read(b[:])
540		return hex.EncodeToString(b[:])
541	}
542

