21	// PreviewRecovery 预览将恢复的内容而不改写存档。
22	//
23	// 传入槽名与调用方可接受的规则版本集合，返回槽当前指向的记录标识、选中
24	// 的来源记录标识及其完整世界状态。来源按本槽“保存生效次序”选择最近一份
25	// 格式受支持、内容与父关系校验通过且版本可接受的记录，越过缺失、截断、
26	// 格式版本不受支持、校验失败与版本不被接受的记录；分支只在分支自身的
27	// 历史中选择，不跨入来源槽。当前记录本就完好且版本可接受时可以选中它本身。
28	//
29	// 槽不存在返回 *NotFoundError；槽指针无法解析，或顶层 latest/history
30	// 字段重复（含义有歧义）时，返回带槽名的 *CorruptError，不返回当前标识或
31	// 恢复来源，也不按任意一份历史继续查找。指针本身可读、只是其指向的当前
32	// 记录已损坏或被删除时不属于这种情况：预览仍返回该当前标识用于之后确认；
33	// 槽中没有任何可用记录时返回包装了 ErrUnrecoverable 的 *UnrecoverableError。
34	// 预览绝不写入、修补或删除任何数据，可重复调用。
35	func (a *Archive) PreviewRecovery(slot string, acceptedVersions []string) (RecoveryPreview, error) {
36		if !validSlotName(slot) {
37			return RecoveryPreview{}, &NotFoundError{Slot: slot}
38		}
39		lock, err := acquireSharedLock(a.dir)
40		if err != nil {
41			return RecoveryPreview{}, err
42		}
43		defer lock.release()
44		return a.previewRecoveryLocked(slot, acceptedVersions)
45	}
