47	// previewRecoveryLocked 在调用方已持锁（共享或排他均可）的前提下执行预览。
48	func (a *Archive) previewRecoveryLocked(slot string, acceptedVersions []string) (RecoveryPreview, error) {
49		pointer, err := a.readSlotPointerLocked(slot)
50		if err != nil {
51			return RecoveryPreview{}, err
52		}
53		// slotHistoryLocked 以指针当前指向为链头，并负责旧格式裸指针沿可信
54		// 父链的重建；当前记录损坏或缺失只会让重建停在那里，不妨碍指针内嵌
55		// 历史索引中更早的本槽记录成为候选。
56		history, err := a.slotHistoryLocked(slot)
57		if err != nil {
58			return RecoveryPreview{}, err
59		}
60		env, err := a.firstRecoverableLocked(history, acceptedVersions)
61		if err != nil {
62			var ue *UnrecoverableError
63			if errors.As(err, &ue) {
64				ue.Slot = slot
65			}
66			return RecoveryPreview{}, err
67		}
68		return RecoveryPreview{
69			Current: pointer.Latest,
70			Source:  env.ID,
71			State:   cloneState(env.State),
72		}, nil
73	}
74	
75	// ConfirmRecovery 把预览选中的来源记录正式保存回本槽并继续使用。
76	//
77	// 入参为槽名、预览返回的当前记录标识 current 与来源记录标识 source，以及
78	// 调用方可接受的规则版本集合。确认在排他锁下重新判断全部前提，绝不使用
79	// 调用方可能修改过的预览状态，而是重新读取并校验来源记录：
80	//
81	//   - current 或 source 为空，或槽已不再指向 current（被并发覆盖、升级
82	//     或另一次恢复抢先提交），返回 *ConflictError。比较只针对槽所指记录，
83	//     即使它已损坏或被删除也不例外，因此损坏/删除的当前标识不会妨碍从
84	//     本槽完好旧记录恢复。
85	//   - 槽指针无法解析，或顶层 latest/history 字段重复（含义有歧义）时，
86	//     返回带槽名的 *CorruptError：确认所需的当前标识与历史次序都无法确定，
87	//     不按任意一份历史挑选来源，不产生新记录，也不修补指针。
88	//   - 来源必须仍属于该槽、格式受支持、仍能通过内容与父关系校验且版本
89	//     可接受。其他槽
90	//     的记录、未生效的残留/孤儿记录按 *NotFoundError 拒绝；来源后来被
91	//     删除返回 *NotFoundError，损坏（截断、格式版本不受支持、校验失败、
92	//     父关系断裂）返回
93	//     *CorruptError，版本不再被接受返回 *VersionRejectedError。来源失效
94	//     时不改选其他记录。
95	//
96	// 成功后产生一条独立的新记录（即使来源就是当前记录），槽指向新记录，
97	// 新记录以来源为父，种子、完整规则、时间片、角色及物品的内容和排列原样
98	// 复制，允许时间片回到来源时刻。旧历史按原保存次序保留，新记录排在最
99	// 前；来源之后仍完好的旧记录可照常读取或分支，已存在的分支不受影响。
100	// 同一 current 上的并发确认、以及确认与普通覆盖或规则升级竞争时，最多
101	// 一个成功。
102	func (a *Archive) ConfirmRecovery(slot string, current, source RecordID, acceptedVersions []string) (RecordInfo, error) {
103		if !validSlotName(slot) {
104			return RecordInfo{}, &NotFoundError{Slot: slot}
105		}
106		if current == "" || source == "" {
107			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "确认恢复必须提供当前记录标识与来源记录标识"}
108		}
109	
110		lock, err := acquireLock(a.dir)
111		if err != nil {
112			return RecordInfo{}, err
113		}
114		defer lock.release()
115	
116		oldPointer, err := a.readSlotPointerLocked(slot)
117		if err != nil {
118			return RecordInfo{}, err
119		}
120		// 乐观并发控制：只有槽仍指向预览时的当前记录才允许确认。当前记录
121		// 本身可能已损坏或被删除——那正是需要恢复的情形——故这里只比较标识，
122		// 不读取它。
123		if oldPointer.Latest != current {
124			return RecordInfo{}, &ConflictError{
125				Slot:   slot,
126				Reason: "槽当前记录已改变，请重新预览后再确认",
127			}
128		}
129	
130		// 来源必须仍在本槽保存次序内：其他槽记录与未生效的孤儿/残留记录
131		// 都不在其中，按记录不存在拒绝。
132		history, err := a.slotHistoryLocked(slot)
133		if err != nil {
134			return RecordInfo{}, err
135		}
136		if err := assertRecordInOrder(history, source); err != nil {
137			return RecordInfo{}, &NotFoundError{Slot: slot, Record: source}
138		}
139	
140		// 重新读取并完整校验来源，不采信调用方带回的任何状态。
141		env, err := a.loadAndVerifyLocked(source)
142		if err != nil {
143			if ce, ok := err.(*CorruptError); ok {
144				ce.Slot = slot
145			}
146			return RecordInfo{}, err
147		}
148		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
149			return RecordInfo{}, &VersionRejectedError{
150				Slot:     slot,
151				Record:   source,
152				Version:  env.State.Rules.Version,
153				Accepted: append([]string(nil), acceptedVersions...),
154			}
155		}
156	
157		// 以选中的来源为父（即使来源就是当前记录，仍保存一条独立新记录），
158		// 种子、完整规则、时间片、角色及物品的内容和排列原样复制，允许时间
159		// 片回到来源时刻。历史承接点用槽指针的当前指向：当前记录已损坏或被
160		// 删除时不能去校验它，但来源之后已经生效的本槽历史仍要原样保留，不
161		// 沿来源的父链截断。沿用共同的组装、落盘与槽指针提交路径。
162		return a.appendSlotRecordLocked(slotSave{
163			slot:          slot,
164			oldPointer:    oldPointer,
165			parent:        source,
166			historyAnchor: oldPointer.Latest,
167			state:         cloneState(env.State),
168		})
169	}
170	
171	// assertRecordInOrder 确认 id 出现在按保存生效次序排列的标识序列中。
172	func assertRecordInOrder(order []RecordID, id RecordID) error {
173		for _, cid := range order {
174			if cid == id {
175				return nil
176			}
177		}
178		return &NotFoundError{Record: id}
179	}
