338			// latest 以 Unicode 转义书写（l -> l），只出现一次。
339			fmt.Sprintf("{\"%s\": %q, \"history\": %s}", escLatestKey, ids[0], quotedRecordIDs(ids)),
340			// history 以 Unicode 转义书写（h -> h），只出现一次。
341			fmt.Sprintf("{\"latest\": %q, \"%s\": %s}", ids[0], escHistoryKey, quotedRecordIDs(ids)),
342			// 旧版本裸指针：没有 history 字段，沿校验通过的父链重建历史。
343			fmt.Sprintf(`{"latest": %q}`, ids[0]),
344			// 不映射到任何固定字段的多余键即使彼此仅大小写不同，也不被解释为
345			// latest/history，继续按原方式忽略。
346			fmt.Sprintf(`{"latest": %q, "history": %s, "extra": 1, "Extra": 2}`,
347				ids[0], quotedRecordIDs(ids)),
348		}
349		for i, raw := range variants {
350			writePointerRaw(t, a, "s", raw)
351	
352			rec, err := a.Latest("s", v1)
353			if err != nil {
354				t.Fatalf("变体 %d 只出现一次的可接受写法应继续可读: %v\n%s", i, err, raw)
355			}
356			if rec.ID != ids[0] {
357				t.Fatalf("变体 %d 当前标识错误: %s", i, rec.ID)
358			}
359			infos, err := a.History("s")
360			if err != nil {
361				t.Fatalf("变体 %d 历史应可读（裸指针可重建）: %v", i, err)
362			}
363			if len(infos) != len(ids) || infos[0].ID != ids[0] || infos[len(ids)-1].ID != ids[2] {
364				t.Fatalf("变体 %d 历史次序错误: %+v", i, infos)
365			}
366		}
367	
368		// 重开后旧裸指针仍只读可用。
369		writePointerRaw(t, a, "s", fmt.Sprintf(`{"latest": %q}`, ids[0]))
370		a2, err := Open(dir)
371		if err != nil {
372			t.Fatal(err)
373		}
374		if rec, err := a2.RecoverLatest("s", v1); err != nil || rec.ID != ids[0] {
375			t.Fatalf("旧裸指针恢复读取应继续可用: %+v err=%v", rec, err)
376		}
377	}
378	
379	// TestSlotPointerDuplicateRecordIDInHistoryUnchanged history 数组里同一记录
380	// 标识出现多次，与字段名称写两次是不同情况：浏览继续按首次出现次序去重，
381	// Latest、Record 与恢复读取照常工作，不能误报字段重复。
382	func TestSlotPointerDuplicateRecordIDInHistoryUnchanged(t *testing.T) {
383		a, _ := newTestArchive(t)
384		ids := saveN(t, a, "s", 2)
385		withDup := append([]RecordID{ids[0]}, ids...) // r2, r2, r1, r0
386		writePointerRaw(t, a, "s",
387			fmt.Sprintf(`{"latest": %q, "history": %s}`, ids[0], quotedRecordIDs(withDup)))
388	
389		if _, err := a.Latest("s", []string{"v1"}); err != nil {
390			t.Fatalf("history 数组内标识重复不是字段重复，Latest 应可读: %v", err)
391		}
392		infos, err := a.History("s")
393		if err != nil {
394			t.Fatalf("history 数组内标识重复不应让浏览失败: %v", err)
395		}
396		if len(infos) != len(ids) {
397			t.Fatalf("应按首次出现次序去重: %+v", infos)
398		}
399		for i, want := range ids {
400			if infos[i].ID != want {
401				t.Fatalf("去重后次序应保持不变: %+v", infos)
402			}
403		}
404		if _, err := a.Record("s", ids[1], []string{"v1"}); err != nil {
405			t.Fatalf("历史记录应可读: %v", err)
406		}
407		if rec, err := a.RecoverLatest("s", []string{"v1"}); err != nil || rec.ID != ids[0] {
408			t.Fatalf("恢复读取应正常: rec=%+v err=%v", rec, err)
409		}
410	}
411	
412	// TestSlotPointerCorruptDoesNotAffectOtherSlots 一个槽的指针字段重复不影响
413	// 打开存档目录、列出槽位或使用其他正常槽；损坏槽也不会被 Slots 悄悄隐藏。
414	func TestSlotPointerCorruptDoesNotAffectOtherSlots(t *testing.T) {
415		a, dir := newTestArchive(t)
416		bad := saveBase(t, a, "bad")
417		good := saveBase(t, a, "good")
418		writePointerRaw(t, a, "bad",
419			fmt.Sprintf(`{"latest": %q, "latest": %q}`, bad.ID, good.ID))
420	
421		a2, err := Open(dir)
422		if err != nil {
423			t.Fatalf("存档目录应能打开: %v", err)
424		}
425		names, err := a2.Slots()
426		if err != nil {
427			t.Fatal(err)
428		}
429		seen := map[string]bool{}
430		for _, n := range names {
431			seen[n] = true
432		}
433		if !seen["bad"] || !seen["good"] {
434			t.Fatalf("两个槽都应仍被列出: %v", names)
435		}
436		if _, err := a2.Latest("good", []string{"v1"}); err != nil {
437			t.Fatalf("正常槽应继续可读: %v", err)
438		}
439		if _, err := a2.History("good"); err != nil {
440			t.Fatalf("正常槽历史应继续可浏览: %v", err)
441		}
442		if _, err := a2.Latest("bad", []string{"v1"}); err == nil {
443			t.Fatal("坏槽应继续报损坏")
444		} else {
445			assertPointerDuplicateCorrupt(t, err, "bad")
446		}
447	}
